import{_ as u,C as l,o as s,c as p,a9 as a,b as i,w as t,a as n,E as o,a8 as d}from"./chunks/framework.BOiBTRPC.js";const C=JSON.parse('{"title":"Data-Intensive Foundations","description":"Reliability, scalability, maintainability — plus CAP, PACELC, replication, partitioning, isolation, consensus, and clocks. The DDIA core, compressed to what production and interviews actually test.","frontmatter":{"title":"Data-Intensive Foundations","description":"Reliability, scalability, maintainability — plus CAP, PACELC, replication, partitioning, isolation, consensus, and clocks. The DDIA core, compressed to what production and interviews actually test."},"headers":[],"relativePath":"system-design/data-intensive.md","filePath":"system-design/data-intensive.md"}'),m={name:"system-design/data-intensive.md"};function g(y,e,b,f,w,v){const r=l("Mermaid"),h=l("HashRingViz"),c=l("QuizCard");return s(),p("div",null,[e[7]||(e[7]=a('<h1 id="data-intensive-foundations" tabindex="-1">Data-Intensive Foundations <a class="header-anchor" href="#data-intensive-foundations" aria-label="Permalink to &quot;Data-Intensive Foundations&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — Every system you build — warehouse, Kafka cluster, CDC pipeline — is a distributed system making silent trade-offs between consistency, availability, and latency. When a dashboard shows stale rows or a failover corrupts a partition, the engineers who can name the trade-off fix it in an hour; everyone else files a ticket.</p></blockquote><h2 id="the-frame-reliability-scalability-maintainability" tabindex="-1">The frame: reliability, scalability, maintainability <a class="header-anchor" href="#the-frame-reliability-scalability-maintainability" aria-label="Permalink to &quot;The frame: reliability, scalability, maintainability&quot;">​</a></h2><p>Kleppmann&#39;s <em>Designing Data-Intensive Applications</em> opens with the only three properties that matter. Everything else in this chapter is mechanism for achieving them.</p><table tabindex="0"><thead><tr><th>Property</th><th>Question</th><th>Data-engineering translation</th></tr></thead><tbody><tr><td><strong>Reliability</strong></td><td>Does it keep working when things fail?</td><td>A crashed worker retries without duplicating output; a bad upstream file goes to a DLQ, not into prod tables.</td></tr><tr><td><strong>Scalability</strong></td><td>Does it degrade gracefully as load grows?</td><td>Adding partitions/nodes increases throughput ~linearly; p99 latency stays flat as volume 10×s.</td></tr><tr><td><strong>Maintainability</strong></td><td>Can the next engineer change it safely?</td><td>Schema evolution is compatible, lineage is traceable, and a rerun produces the same answer.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Interviewers use this frame implicitly. When asked to &quot;design X,&quot; narrate which of the three you&#39;re optimizing and what you&#39;re sacrificing — that trade-off narration <em>is</em> the senior signal.</p></div><h3 id="describing-load-and-performance" tabindex="-1">Describing load and performance <a class="header-anchor" href="#describing-load-and-performance" aria-label="Permalink to &quot;Describing load and performance&quot;">​</a></h3><p>Load is described by <strong>load parameters</strong> — the numbers that matter for <em>your</em> system: events/sec, read:write ratio, fan-out (one write → how many reads), active entities. Performance is latency <strong>percentiles</strong> (p50/p95/p99), never averages — the p99 is what your slowest customers experience and what tails-of-distribution bugs live behind.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>Mean latency hides the failure. A pipeline averaging 200 ms with a p99 of 30 s means 1% of requests — often the biggest customers with the most data — are nearly timing out. Always SLO on percentiles.</p></div><h2 id="cap-and-pacelc" tabindex="-1">CAP and PACELC <a class="header-anchor" href="#cap-and-pacelc" aria-label="Permalink to &quot;CAP and PACELC&quot;">​</a></h2><p><strong>CAP</strong>: under a network <strong>P</strong>artition, a system must choose between <strong>C</strong>onsistency (every read sees the latest write or errors) and <strong>A</strong>vailability (every request gets a non-error response). The nuance people miss:</p><ul><li>C + A is not &quot;impossible&quot; — it&#39;s impossible <strong>only during a partition</strong>. When the network is healthy you can have both.</li><li>You don&#39;t pick &quot;two of three&quot; once. You pick <strong>CP or AP per subsystem, per partition event</strong>. Your auth service might refuse writes (CP) while your dashboard serves stale data happily (AP).</li><li>&quot;CA systems&quot; don&#39;t exist in distributed systems — if it can partition (and it can), the choice is forced.</li></ul><p><strong>PACELC</strong> extends this to the healthy case: <strong>i</strong>f <strong>P</strong>artition, choose <strong>A</strong>vailability or <strong>C</strong>onsistency; <strong>E</strong>lse, choose <strong>L</strong>atency or <strong>C</strong>onsistency. The EL half is the one you live with daily: synchronous replication gives consistency but adds cross-AZ/region RTT to every write; asynchronous replication is fast but can lose recent writes on failover.</p>',13)),(s(),i(d,null,{default:t(()=>[o(r,{id:"mermaid-106",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20P%7B%22Network%20partition%3F%22%7D%20--%3E%7C%22yes%22%7C%20Q%7B%22Refuse%20writes%20or%20serve%20stale%3F%22%7D%0A%20%20%20%20P%20--%3E%7C%22no%20%E2%80%94%20normal%20operation%22%7C%20R%7B%22Replicate%20sync%20or%20async%3F%22%7D%0A%20%20%20%20Q%20--%3E%7C%22refuse%20%E2%80%94%20CP%22%7C%20CP%5B%22Consistency%3A%20bank%20ledger%2C%20config%20store%22%5D%0A%20%20%20%20Q%20--%3E%7C%22serve%20stale%20%E2%80%94%20AP%22%7C%20AP%5B%22Availability%3A%20metrics%2C%20session%20carts%2C%20feeds%22%5D%0A%20%20%20%20R%20--%3E%7C%22sync%20%E2%80%94%20LC%22%7C%20LC%5B%22Consistent%20but%20slower%20writes%22%5D%0A%20%20%20%20R%20--%3E%7C%22async%20%E2%80%94%20LL%22%7C%20LL%5B%22Fast%20writes%2C%20replication%20lag%20risk%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=a('<div class="info custom-block"><p class="custom-block-title">ℹ️</p><p>Practical cheat sheet: money, inventory counts, leader election → CP. Telemetry, recommendations, presence, dashboards → AP. Most data pipelines are AP systems with a CP control plane (e.g., KRaft/ZooKeeper for metadata).</p></div><h3 id="picking-cp-vs-ap-per-subsystem" tabindex="-1">Picking CP vs AP per subsystem <a class="header-anchor" href="#picking-cp-vs-ap-per-subsystem" aria-label="Permalink to &quot;Picking CP vs AP per subsystem&quot;">​</a></h3><p>The &quot;pick two&quot; framing is wrong; the real question is <em>per data flow, during partition, which do we sacrifice?</em></p><table tabindex="0"><thead><tr><th>Subsystem</th><th>Partition behavior</th><th>Why</th></tr></thead><tbody><tr><td>Control plane / metadata (KRaft, etcd)</td><td>CP — refuse writes without quorum</td><td>Divergent metadata is unrecoverable; unavailability is preferable</td></tr><tr><td>Payment/ledger writes</td><td>CP — fail the write</td><td>A lost or double write is worse than a rejected one</td></tr><tr><td>Metrics, logging, telemetry</td><td>AP — accept and buffer</td><td>Volume is huge; gaps are tolerable; lag already expected</td></tr><tr><td>User-facing reads (feeds, dashboards)</td><td>AP — serve stale</td><td>Stale beats error pages; pair with a freshness SLO</td></tr><tr><td>Session/cart state</td><td>AP with conflict resolution</td><td>Losing a cart item is recoverable UX; downtime isn&#39;t</td></tr></tbody></table><details class="details custom-block"><summary>The C+A nuance, precisely</summary><p>CAP is a theorem about a <em>single register</em> during a partition, not a system taxonomy. A healthy cluster is both consistent and available every day — the theorem only bites when messages are dropped/delayed. Two practical consequences: (1) you can&#39;t &quot;design a CA system&quot; because you can&#39;t opt out of partitions; (2) many real systems are <em>mostly</em> CA and degrade to explicit CP/AP behavior only on failure — which is exactly what PACELC&#39;s ELSE branch describes.</p></details><h2 id="consistency-models" tabindex="-1">Consistency models <a class="header-anchor" href="#consistency-models" aria-label="Permalink to &quot;Consistency models&quot;">​</a></h2><p>Consistency models describe what a client can observe across <strong>replicas</strong>. Weakest at the bottom, most expensive at the top.</p><table tabindex="0"><thead><tr><th>Model</th><th>Guarantee</th><th>Cost</th><th>Where you meet it</th></tr></thead><tbody><tr><td><strong>Linearizable</strong></td><td>Every op appears to happen atomically, in real-time order, on a single copy of the data</td><td>Highest — coordination on every write</td><td>ZooKeeper/etcd, Kafka controller, &quot;leader only&quot; reads</td></tr><tr><td><strong>Sequential</strong></td><td>Ops appear in some order consistent with each client&#39;s program order — but not real-time</td><td>High</td><td>Some quorum reads</td></tr><tr><td><strong>Causal</strong></td><td>Happens-before-related writes seen in order; unrelated may reorder</td><td>Medium</td><td>Version-vector systems</td></tr><tr><td><strong>Read-your-writes</strong></td><td>You always see your own writes</td><td>Low (sticky sessions, read-from-leader)</td><td>User-facing writes; what most products actually need</td></tr><tr><td><strong>Eventual</strong></td><td>If writes stop, replicas converge <em>eventually</em></td><td>Lowest</td><td>Dynamo-style stores, CDC replicas, caches</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>&quot;Eventual consistency&quot; in production usually means <em>a replication lag SLO</em> (e.g., &lt;5 s p99) plus monitoring — not a shrug. The model is weak; the operational contract is what makes it usable.</p></div><h3 id="guarantees-as-user-facing-promises" tabindex="-1">Guarantees as user-facing promises <a class="header-anchor" href="#guarantees-as-user-facing-promises" aria-label="Permalink to &quot;Guarantees as user-facing promises&quot;">​</a></h3><p>The useful way to pick a model isn&#39;t &quot;how strong can we afford&quot; — it&#39;s &quot;what lie will a user notice?&quot; Kleppmann frames replication-lag guarantees as promises the product makes, each with a concrete anomaly it prevents and a cheap mechanism that delivers it.</p><table tabindex="0"><thead><tr><th>Promise</th><th>Anomaly it prevents</th><th>Cheapest mechanism</th><th>DE translation</th></tr></thead><tbody><tr><td><strong>Read-your-writes</strong></td><td>User reloads and their own update vanished — they assume it was lost</td><td>Read own writes from the leader, or route reads to a replica caught up to the client&#39;s last-write timestamp/LSN</td><td>After an UPSERT the same session must read it back; dashboards serving &quot;your recent run&quot; need leader reads or lag-aware routing</td></tr><tr><td><strong>Monotonic reads</strong></td><td>Time appears to go backward — a refresh shows <em>older</em> data than the previous refresh</td><td>Pin each user&#39;s reads to one replica (e.g., hash of user ID)</td><td>Sticky routing on read replicas; matters when a user polls a status endpoint during a long load</td></tr><tr><td><strong>Consistent prefix reads</strong></td><td>Causally related writes appear out of order — an answer shows before its question</td><td>Writes that are causally related go to the same partition</td><td>A CDC consumer applying a delete before the insert it responds to; keep causal chains on one partition key</td></tr><tr><td><strong>Linearizability</strong></td><td>A stale read silently returns — no way to distinguish &quot;unchanged&quot; from &quot;not yet replicated&quot;</td><td>Single leader + coordination (consensus) for reads and writes</td><td>The only model that supports &quot;read, then decide&quot; — compare-and-swap, uniqueness, leader-election leases</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>These are <em>per-user</em> promises, not global ones — read-your-writes says nothing about when other users see your write. That makes them cheap: sticky sessions and LSN-aware routing deliver them without consensus. Reserve linearizability for the tiny surface that actually needs it (locks, unique claims, fencing tokens) — it costs coordination on every operation.</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>Cross-device read-your-writes is the version that bites: sticky sessions by connection don&#39;t survive a user switching from phone to laptop. The robust fix is a client-tracked watermark — each device carries the user&#39;s minimum LSN/timestamp, and any serving replica must be caught up to it or the read waits.</p></div><h3 id="consistency-isolation" tabindex="-1">Consistency ≠ isolation <a class="header-anchor" href="#consistency-isolation" aria-label="Permalink to &quot;Consistency ≠ isolation&quot;">​</a></h3><ul><li><strong>Consistency models</strong> (above) govern <em>replicas</em>: what readers see across copies of the data.</li><li><strong>Isolation levels</strong> (below) govern <em>concurrent transactions</em> inside one database: what interleavings are allowed.</li></ul><p>People conflate them in interviews constantly. Don&#39;t.</p><h2 id="replication" tabindex="-1">Replication <a class="header-anchor" href="#replication" aria-label="Permalink to &quot;Replication&quot;">​</a></h2><p>Why replicate: durability (survive node loss), read scaling, geo-locality. The cost is the consistency problem above.</p>',19)),(s(),i(d,null,{default:t(()=>[o(r,{id:"mermaid-412",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20SingleLeader%5B%22Single-leader%22%5D%0A%20%20%20%20%20%20%20%20W1%5B%22writes%22%5D%20--%3E%20L1%5B%22Leader%22%5D%0A%20%20%20%20%20%20%20%20L1%20--%3E%7C%22sync%20or%20async%20replication%22%7C%20F1%5B%22Follower%22%5D%0A%20%20%20%20%20%20%20%20L1%20--%3E%7C%22sync%20or%20async%20replication%22%7C%20F2%5B%22Follower%22%5D%0A%20%20%20%20%20%20%20%20R1%5B%22reads%22%5D%20--%3E%20F1%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Leaderless%5B%22Leaderless%20%E2%80%94%20Dynamo-style%2C%20n%3D3%2C%20w%3D2%2C%20r%3D2%22%5D%0A%20%20%20%20%20%20%20%20C2%5B%22Client%22%5D%20--%3E%20N1%5B%22replica%201%22%5D%0A%20%20%20%20%20%20%20%20C2%20--%3E%20N2%5B%22replica%202%22%5D%0A%20%20%20%20%20%20%20%20C2%20--%3E%20N3%5B%22replica%203%22%5D%0A%20%20%20%20%20%20%20%20N1%20--%3E%20QR%5B%22read%20quorum%20merges%20versions%22%5D%0A%20%20%20%20%20%20%20%20N2%20--%3E%20QR%0A%20%20%20%20%20%20%20%20N3%20--%3E%20QR%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=a('<table tabindex="0"><thead><tr><th>Topology</th><th>Writes go to</th><th>Conflict handling</th><th>Failure mode</th></tr></thead><tbody><tr><td><strong>Single-leader</strong></td><td>One leader; followers replicate</td><td>None — one write order</td><td>Failover lag; <strong>split-brain</strong> if old leader is resurrected</td></tr><tr><td><strong>Multi-leader</strong></td><td>One leader per region; leaders sync async</td><td>Last-write-wins, CRDTs, app-level</td><td>Conflict storms; divergence if sync breaks</td></tr><tr><td><strong>Leaderless</strong></td><td>Quorum <code>w</code> of <code>n</code> replicas</td><td>Read repair + version vectors/<code>r</code> reads</td><td>Sloppy quorums mask inconsistency; <code>w + r ≤ n</code> reads can miss writes</td></tr></tbody></table><h3 id="quorum-math-in-leaderless-systems" tabindex="-1">Quorum math in leaderless systems <a class="header-anchor" href="#quorum-math-in-leaderless-systems" aria-label="Permalink to &quot;Quorum math in leaderless systems&quot;">​</a></h3><p>In Dynamo-style stores (Cassandra, Riak) there&#39;s no leader: the client (or a coordinator node) sends each write to <code>n</code> replicas and each read to <code>n</code> replicas; <code>w</code> and <code>r</code> responses are needed for success. The rule of thumb:</p><ul><li><strong><code>w + r &gt; n</code></strong> → reads usually see the latest write, because the write set and read set must overlap on at least one node. Common choices: <code>n=3, w=r=2</code> (tolerates one node down) or <code>w=1, r=3</code> for read-heavy data.</li><li><strong><code>w + r ≤ n</code></strong> → a read can legitimately miss a committed write; you get eventual convergence, not a guarantee.</li><li><code>w + r &gt; n</code> is <em>not</em> a hard guarantee — it&#39;s probabilistic. Concurrent writes, clock-skewed last-write-wins, or a write that landed while a read raced ahead can still return stale values. Sloppy quorums (below) make even the overlap uncertain.</li></ul><p><strong>Sloppy quorums and hinted handoff:</strong> when some of a key&#39;s <code>n</code> &quot;home&quot; nodes are unreachable, a strict quorum fails — so Dynamo-style systems let <em>any</em> reachable node hold the write. <code>w</code> acknowledgments still succeed, but some live on stand-in nodes outside the <code>n</code>. When the real home node recovers, the stand-ins forward it the writes — <strong>hinted handoff</strong>. The catch: now even <code>w + r &gt; n</code> doesn&#39;t promise the latest read, because the newest value may sit on a node outside the <code>n</code> your read contacts. A sloppy quorum isn&#39;t really a quorum — it&#39;s a <em>durability</em> promise (&quot;stored on <code>w</code> nodes somewhere&quot;), not a consistency one.</p>',5)),(s(),i(d,null,{default:t(()=>[o(r,{id:"mermaid-501",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20C%5B%22client%20write%20%E2%80%94%20w%20%3D%202%22%5D%20--%3E%20N1%5B%22home%20node%201%22%5D%0A%20%20%20%20C%20--%3E%20H%5B%22stand-in%20node%20%E2%80%94%20home%20node%203%20unreachable%22%5D%0A%20%20%20%20H%20-.-%3E%7C%22hinted%20handoff%20once%20node%203%20recovers%22%7C%20N3%5B%22home%20node%203%22%5D%0A%20%20%20%20RQ%5B%22read%20quorum%20%E2%80%94%20r%20%3D%202%22%5D%20--%3E%20N1%0A%20%20%20%20RQ%20--%3E%20N3%0A%20%20%20%20N3%20-.-%3E%7C%22hint%20not%20arrived%20yet%20%E2%80%94%20stale%20read%22%7C%20RQ%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[n(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=a('<details class="details custom-block"><summary>Where you tune this in real systems</summary><p>Cassandra exposes <code>CONSISTENCY ONE | QUORUM | ALL</code> per query; Riak exposes <code>r</code>/<code>w</code>/<code>n</code> per bucket. The operational knob is the same either way: raising <code>w</code> buys durability at the cost of write availability during partial outages, and sloppy quorum settings (<code>sloppy_quorum</code> in Riak, hinted handoff in Cassandra) buy write availability at the cost of stale reads until handoff completes. Watch hinted-handoff backlog metrics — a growing backlog means your reads are quietly time-traveling.</p></details><h3 id="the-split-brain-problem" tabindex="-1">The split-brain problem <a class="header-anchor" href="#the-split-brain-problem" aria-label="Permalink to &quot;The split-brain problem&quot;">​</a></h3><p>Single-leader failover has a classic trap: the leader&#39;s heartbeats time out, a follower is promoted — but the old leader was only <em>slow</em> (GC pause, network blip), not dead. Now two nodes accept writes and the replicas diverge. The fix: <strong>fencing</strong> — the new leader gets a monotonically increasing term/epoch (from the consensus layer), and any node with a stale epoch is rejected by storage. This is why systems like Kafka&#39;s KRaft and etcd exist: they don&#39;t just elect leaders, they <em>fence</em> old ones.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>Split-brain isn&#39;t exotic — it happens on every long GC pause under aggressive timeouts. If your failover script doesn&#39;t fence the old leader (STONITH, epoch checks, or storage-level lease revocation), a &quot;successful&quot; failover can silently fork your data.</p></div><h2 id="partitioning" tabindex="-1">Partitioning <a class="header-anchor" href="#partitioning" aria-label="Permalink to &quot;Partitioning&quot;">​</a></h2><p>Replication copies the same data; partitioning splits it. Goal: spread load evenly so <code>n</code> nodes ≈ <code>n</code>× throughput.</p><table tabindex="0"><thead><tr><th>Strategy</th><th>How</th><th>Pros</th><th>Cons</th></tr></thead><tbody><tr><td><strong>Hash partitioning</strong></td><td><code>hash(key) mod n</code></td><td>Even load, no range hotspots</td><td>Loses ordering; range scans hit all partitions; reshuffling on <code>mod</code></td></tr><tr><td><strong>Range partitioning</strong></td><td>Sorted key ranges per shard</td><td>Range scans and sorted reads are cheap</td><td>Hot spots on monotonic keys (timestamps!); needs splitting</td></tr><tr><td><strong>Compound</strong></td><td>Hash within range, or vice versa</td><td>Best of both (e.g., partition by date, hash by user)</td><td>Complexity</td></tr></tbody></table><p><strong>Consistent hashing</strong> (hashing nodes and keys onto a ring, moving only <code>k/n</code> keys on membership change) is the standard answer to &quot;what happens when we add a node?&quot; — vanilla <code>mod n</code> reshuffles almost everything.</p>',8)),o(h),e[11]||(e[11]=a('<p>Try the buttons: <strong>Add node</strong> inserts a node at a fixed ring position — only the keys in the arc between it and its predecessor change color, which is exactly the &quot;move <code>k/n</code> keys&quot; property. <strong>Remove node</strong> hands that node&#39;s arc to the next node clockwise — again a small local move. Then toggle <strong>Naive mod-N</strong>: the same membership change recolors almost every key, because the modulus itself changed. That visual difference is why caches, shard maps, and job-routing tables use consistent hashing — a reshuffle under <code>mod n</code> means a cold cache or a full data migration; a ring means a bounded rebalance.</p><details class="details custom-block"><summary>Why the ring still needs care</summary><p>Hashing nodes onto the ring gives each node a <em>random</em> arc — with few nodes the arcs are uneven, so load is uneven. Real systems fix this with <strong>virtual nodes</strong> (each physical node claims many ring positions, smoothing the distribution — Cassandra&#39;s vnodes, Ketama in memcached clients). The interactive above uses one position per node for clarity; multiply each by ~100 vnodes and the arc sizes equalize while the <code>k/n</code> move property survives.</p></details><h3 id="hot-spots-and-the-celebrity-problem" tabindex="-1">Hot spots and the celebrity problem <a class="header-anchor" href="#hot-spots-and-the-celebrity-problem" aria-label="Permalink to &quot;Hot spots and the celebrity problem&quot;">​</a></h3><p>No scheme saves a skewed <em>key</em>. If one user_id generates 30% of writes, whichever partition owns it melts while others idle. Mitigations: <strong>key salting</strong> (append a random bucket suffix <code>user_123#7</code> to spread one key across partitions, at the cost of scatter-gather reads), dedicated &quot;celebrity&quot; partitions, or two-phase aggregation.</p><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>This is <em>the</em> most common real partitioning failure — not picking hash vs range, but discovering post-launch that 3 keys own 40% of traffic. Always ask &quot;what does the key distribution look like?&quot; before discussing the partitioning function.</p></div><h2 id="isolation-levels-and-anomalies" tabindex="-1">Isolation levels and anomalies <a class="header-anchor" href="#isolation-levels-and-anomalies" aria-label="Permalink to &quot;Isolation levels and anomalies&quot;">​</a></h2><p>Inside a transactional store, isolation controls what concurrent transactions can observe. Anomalies by level:</p><table tabindex="0"><thead><tr><th>Isolation</th><th>Dirty read</th><th>Non-repeatable read</th><th>Phantom</th><th>Write skew / lost update</th></tr></thead><tbody><tr><td>Read uncommitted</td><td>✅ possible</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Read committed</td><td>❌</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Repeatable read</td><td>❌</td><td>❌</td><td>✅ (mostly prevented in InnoDB/Postgres)</td><td>✅ write skew</td></tr><tr><td>Serializable</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td></tr></tbody></table><p>Two anomalies worth knowing cold:</p><ul><li><strong>Lost update</strong>: two transactions read-modify-write the same row; the second commit overwrites the first. Fix with atomic operations, explicit <code>SELECT ... FOR UPDATE</code> locking, or compare-and-swap.</li><li><strong>Write skew</strong>: each transaction&#39;s writes are individually valid but together violate an invariant — e.g., two on-call doctors both see &quot;≥1 on call&quot; and both sign off, leaving zero. Only true serializability (or materialized locks on the <em>predicate</em>, e.g. a dedicated row) prevents it.</li></ul><div class="info custom-block"><p class="custom-block-title">ℹ️</p><p>Postgres &quot;repeatable read&quot; already prevents phantoms via snapshot isolation — its serializable level adds SSI (Serializable Snapshot Isolation) to catch write skew. Default is read committed; most ORMs leave it there.</p></div><h3 id="how-serializability-is-actually-implemented" tabindex="-1">How serializability is actually implemented <a class="header-anchor" href="#how-serializability-is-actually-implemented" aria-label="Permalink to &quot;How serializability is actually implemented&quot;">​</a></h3><p>&quot;Serializable&quot; is a guarantee, not a mechanism. Three families deliver it, with very different costs:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Idea</th><th>Concurrency style</th><th>The catch</th><th>Where</th></tr></thead><tbody><tr><td><strong>Actual serial execution</strong></td><td>One thread executes transactions in order; no concurrency at all</td><td>None — ordered</td><td>Only works if transactions are short, fast, and fit in one node&#39;s memory</td><td>VoltDB, Redis (mostly), stored-procedure-per-partition designs</td></tr><tr><td><strong>Two-phase locking (2PL)</strong></td><td>Shared locks for reads, exclusive for writes; acquire in phase 1, release in phase 2 — writers block readers <em>and</em> vice versa</td><td>Pessimistic</td><td>Deadlocks need detection + abort; lock contention crushes throughput at hot rows; famously poor latency</td><td>MySQL/InnoDB serializable, SQL Server, DB2 repeatable read</td></tr><tr><td><strong>Serializable Snapshot Isolation (SSI)</strong></td><td>Transactions run on a snapshot (readers never block writers); the DB tracks read/write dependencies and aborts a transaction when it detects a dangerous interleaving</td><td>Optimistic</td><td>Aborts under contention — long/high-conflict transactions get retried; needs retry logic in the app</td><td>Postgres serializable, CockroachDB-style MVCC+validation</td></tr></tbody></table><p>The pessimistic-vs-optimistic split is the interview-worthy part: <strong>2PL</strong> makes every conflict wait (throughput dies under contention but nothing is wasted), <strong>SSI</strong> lets conflicts proceed and aborts the loser (great throughput when conflicts are rare, wasted work when they&#39;re common). Pick by contention profile — hot-row workloads suffer under both, which is why inventory counters end up as explicit CAS loops or queued writes instead.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>SSI&#39;s failure mode is silent in dev: aborts only appear under <em>real</em> concurrency. Code that passes tests on Postgres <code>SERIALIZABLE</code> can abort-storm in production if it lacks bounded retry with backoff — and an unbounded retry loop on a hot conflict is a livelock, not a fix.</p></div><h2 id="consensus-and-clocks" tabindex="-1">Consensus and clocks <a class="header-anchor" href="#consensus-and-clocks" aria-label="Permalink to &quot;Consensus and clocks&quot;">​</a></h2><h3 id="raft-intuition" tabindex="-1">Raft intuition <a class="header-anchor" href="#raft-intuition" aria-label="Permalink to &quot;Raft intuition&quot;">​</a></h3><p>Consensus = getting <code>n</code> unreliable nodes to agree on one value/order despite failures. Raft does it with <strong>terms</strong> and <strong>majority quorums</strong>:</p>',19)),(s(),i(d,null,{default:t(()=>[o(r,{id:"mermaid-824",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20A%20as%20Node%20A%0A%20%20%20%20participant%20B%20as%20Node%20B%0A%20%20%20%20participant%20C%20as%20Node%20C%0A%20%20%20%20Note%20over%20A%3A%20election%20timeout%20%E2%80%94%20no%20heartbeat%0A%20%20%20%20A-%3E%3EB%3A%20RequestVote%20term%207%0A%20%20%20%20A-%3E%3EC%3A%20RequestVote%20term%207%0A%20%20%20%20B--%3E%3EA%3A%20granted%0A%20%20%20%20C--%3E%3EA%3A%20granted%0A%20%20%20%20Note%20over%20A%3A%20majority%20of%203%20%E2%80%94%20A%20is%20leader%20for%20term%207%0A%20%20%20%20A-%3E%3EB%3A%20AppendEntries%20heartbeats%0A%20%20%20%20A-%3E%3EC%3A%20AppendEntries%20heartbeats%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[n(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=a('<p>Key properties that matter operationally:</p><ul><li><strong>Leader election</strong> happens on heartbeat timeout; a node needs a majority of votes. A 2-2 split elects no leader — no candidate reaches majority, so the cluster stays leaderless until re-election with randomized timeouts. Another reason for odd replica counts.</li><li><strong>Terms double as fencing tokens</strong>: a node that sees a higher term steps down. This is what prevents split-brain writes (above).</li><li><strong>Committed = replicated to a majority.</strong> A leader can only serve reads/writes for entries a majority has. Lose your majority (2 of 3 nodes down) and the cluster goes read-only — by design.</li></ul><details class="details custom-block"><summary>Why odd numbers, and why consensus is everywhere in DE</summary><p>A 5-node cluster tolerates 2 failures; a 6-node cluster also tolerates only 2 — so 5 is strictly better than 6. You meet this machinery constantly in data engineering: Kafka&#39;s KRaft metadata, ZooKeeper, etcd, Raft-backed coordination in ClickHouse Keeper, Pinot, and most control planes. You rarely <em>build</em> consensus; you operate systems whose availability is governed by it.</p></details><h3 id="clocks-why-you-can-t-trust-timestamps" tabindex="-1">Clocks: why you can&#39;t trust timestamps <a class="header-anchor" href="#clocks-why-you-can-t-trust-timestamps" aria-label="Permalink to &quot;Clocks: why you can&#39;t trust timestamps&quot;">​</a></h3><ul><li><strong>NTP clock drift</strong>: machine clocks drift (±ms to seconds); NTP can <em>jump</em> the clock backward, breaking &quot;later timestamp = newer data&quot; assumptions. Never use wall-clock time alone to order events or pick &quot;latest&quot; versions.</li><li><strong>Happens-before / Lamport clocks</strong>: if A → B causally, A&#39;s logical clock &lt; B&#39;s — but the converse doesn&#39;t hold. Lamport orders <em>causally related</em> events; it can&#39;t compare concurrent ones.</li><li><strong>Vector clocks</strong> track per-node counters and detect true concurrency (used in Dynamo-style conflict detection).</li><li><strong>Hybrid Logical Clocks</strong> (HLC): wall clock + logical counter — bounded drift, causally ordered, and human-readable. Used by CockroachDB, YugabyteDB, and Azure Cosmos DB for distributed ordering without physical-clock trust.</li></ul>',5)),(s(),i(d,null,{default:t(()=>[o(r,{id:"mermaid-875",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20E1%5B%22event%20A%20on%20node%201%22%5D%20--%3E%7C%22causal%22%7C%20E2%5B%22event%20B%20on%20node%203%22%5D%0A%20%20%20%20E3%5B%22event%20C%20on%20node%202%20%E2%80%94%20concurrent%20with%20B%22%5D%0A%20%20%20%20E1%20---%20E3%0A%20%20%20%20E2%20-.-%3E%7C%22B%20and%20C%20are%20concurrent%20%E2%80%94%20no%20total%20order%20exists%22%7C%20E3%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[n(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=a('<div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>&quot;Last write wins&quot; ordered by client/ingest wall-clock timestamps is the single most common clock bug in pipelines — clock-skewed producers make the <em>wrong</em> write &quot;win.&quot; Use event-time + watermarks with explicit late-data policy, or sequence numbers/offsets assigned by a single authority.</p></div><h3 id="end-to-end-ordering-total-order-broadcast" tabindex="-1">End-to-end ordering: total order broadcast <a class="header-anchor" href="#end-to-end-ordering-total-order-broadcast" aria-label="Permalink to &quot;End-to-end ordering: total order broadcast&quot;">​</a></h3><p>Clocks and Lamport timestamps give each <em>pair</em> of events an order, but they can&#39;t give the whole system one agreed sequence — a Lamport total order exists on paper, yet no node can know it in real time (you can&#39;t tell whether a &quot;later&quot; event is still in flight). The distributed-systems name for the thing that actually works is <strong>total order broadcast</strong>: a protocol with two safety properties —</p><ul><li><strong>Reliable delivery</strong>: if a message is delivered to one node, it&#39;s delivered to all nodes (retrying through failures).</li><li><strong>Totally ordered delivery</strong>: every node receives the same messages in the same order.</li></ul><p>This is exactly what consensus services implement: ZooKeeper, etcd, and Kafka&#39;s KRaft are, underneath, total-order-broadcast machines. It&#39;s also what you need for database replication and fencing — a single ordered log of operations that every node applies in sequence is the difference between &quot;replicas that probably converge&quot; and &quot;replicas that are the same state machine.&quot;</p>',5)),(s(),i(d,null,{default:t(()=>[o(r,{id:"mermaid-902",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20P1%5B%22producer%201%22%5D%20--%3E%20LOG%5B%22totally%20ordered%20log%22%5D%0A%20%20%20%20P2%5B%22producer%202%22%5D%20--%3E%20LOG%0A%20%20%20%20P3%5B%22producer%203%22%5D%20--%3E%20LOG%0A%20%20%20%20LOG%20--%3E%7C%22same%20sequence%2C%20same%20offsets%22%7C%20C1%5B%22consumer%20%2F%20replica%201%22%5D%0A%20%20%20%20LOG%20--%3E%20C2%5B%22consumer%20%2F%20replica%202%22%5D%0A%20%20%20%20LOG%20--%3E%20C3%5B%22consumer%20%2F%20replica%203%22%5D%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[n(" Loading... ",-1)])]),_:1})),e[14]||(e[14]=a('<p>The scope caveat matters for DE: ordering is usually <strong>per partition</strong>, not global. Kafka gives a total order inside each partition; nothing orders a message in partition 3 against one in partition 7. That&#39;s why causal chains must share a partition key (consistent prefix reads, above) and why cross-partition invariants (uniqueness across shards) still need a coordinating authority.</p><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Total order broadcast is consensus in work clothes — they&#39;re provably equivalent problems. Practical consequence: wherever you need &quot;everyone agrees on the sequence&quot; (leader election, fencing tokens, DDL propagation, schema registry versions), you&#39;re already standing on a consensus log, whether it&#39;s labeled etcd, KRaft, or the Kafka partition itself.</p></div><h2 id="batch-vs-streaming-read-paths" tabindex="-1">Batch vs streaming read paths <a class="header-anchor" href="#batch-vs-streaming-read-paths" aria-label="Permalink to &quot;Batch vs streaming read paths&quot;">​</a></h2><p>The same data reaches consumers through two structurally different paths:</p><table tabindex="0"><thead><tr><th></th><th>Batch path</th><th>Streaming path</th></tr></thead><tbody><tr><td>Data unit</td><td>Bounded snapshot — &quot;data as of T&quot;</td><td>Unbounded event stream</td></tr><tr><td>Consistency</td><td>Strong intra-run — one snapshot, one answer</td><td>Eventual — consumers see events at different lag</td></tr><tr><td>Latency</td><td>Minutes–hours</td><td>ms–seconds</td></tr><tr><td>Reprocessing</td><td>Recompute the snapshot — trivially correct</td><td>Requires replayable log + dedupe; late data is a first-class problem</td></tr><tr><td>Failure mode</td><td>Job fails → rerun whole slice</td><td>Lag, watermark misconfiguration, hot partitions</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>The modern convergence: streaming engines treat batch as &quot;a stream with finite bounds,&quot; and lakehouse tables give streaming sinks a replayable, re-partitionable landing zone. Design the <em>source of truth</em> as an immutable append log; batch and streaming become two readers of the same thing.</p></div><h3 id="the-unifying-frame-derived-data" tabindex="-1">The unifying frame: derived data <a class="header-anchor" href="#the-unifying-frame-derived-data" aria-label="Permalink to &quot;The unifying frame: derived data&quot;">​</a></h3><p>Kleppmann&#39;s Part III reframes the whole batch-vs-stream debate: almost everything downstream of the write path is <strong>derived data</strong> — caches, search indexes, materialized views, warehouses, ML features. The <strong>system of record</strong> is the truth; everything else is a transform you could recompute. Batch and stream processing are then two strategies for the same job — keep derived data in sync with the record:</p><table tabindex="0"><thead><tr><th></th><th>Batch derivation</th><th>Stream derivation</th></tr></thead><tbody><tr><td>Sync mechanism</td><td>Recompute the whole derived dataset from a bounded snapshot</td><td>Incrementally apply each change as it arrives (CDC, event log)</td></tr><tr><td>Rebuild story</td><td>Trivial — rerun the job; output is deterministic</td><td>Replay the log from offset zero — needs the log to be replayable</td></tr><tr><td>State hazard</td><td>None inside a run — one snapshot, one answer</td><td>Late/out-of-order events, watermark tuning, exactly-once bookkeeping</td></tr><tr><td>Why it exists</td><td>Throughput, reproducibility, auditability</td><td>Latency — the record changes continuously and consumers can&#39;t wait</td></tr></tbody></table>',9)),(s(),i(d,null,{default:t(()=>[o(r,{id:"mermaid-1061",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20SOR%5B%22system%20of%20record%20%E2%80%94%20the%20write%20log%22%5D%20--%3E%7C%22CDC%20%2F%20event%20stream%22%7C%20ST%5B%22stream%20job%20%E2%80%94%20incremental%22%5D%0A%20%20%20%20SOR%20--%3E%7C%22bounded%20snapshot%22%7C%20BA%5B%22batch%20job%20%E2%80%94%20full%20recompute%22%5D%0A%20%20%20%20ST%20--%3E%20D1%5B%22search%20index%22%5D%0A%20%20%20%20ST%20--%3E%20D2%5B%22cache%22%5D%0A%20%20%20%20BA%20--%3E%20D3%5B%22warehouse%20tables%22%5D%0A%20%20%20%20BA%20--%3E%20D4%5B%22ML%20features%22%5D%0A"})]),fallback:t(()=>[...e[6]||(e[6]=[n(" Loading... ",-1)])]),_:1})),e[15]||(e[15]=a('<p>The payoff of this framing: <strong>batch and stream are not rival architectures — they&#39;re two readers of one immutable log.</strong> If your system of record is an append-only event log, a search index is just a consumer at some offset, a batch warehouse table is the same consumer run to completion over a bounded range, and &quot;rebuild the index&quot; means &quot;replay the log.&quot; Kleppmann&#39;s version of the lambda-to-kappa evolution follows directly: you don&#39;t need two codebases if the derived systems all consume the same ordered stream.</p><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>When someone asks &quot;batch or streaming for this pipeline?&quot;, the derived-data question dissolves most of the debate: what <em>latency does the consumer of this derived dataset actually need</em>, and is the log replayable enough to rebuild it? Pick the simplest reader that meets the latency SLO — a cron recompute of a derived table beats a streaming job with dedupe, state, and watermarks when &quot;fresh within 6 hours&quot; is the real requirement.</p></div><h2 id="putting-it-together-failure-modes-cheat-sheet" tabindex="-1">Putting it together: failure modes cheat sheet <a class="header-anchor" href="#putting-it-together-failure-modes-cheat-sheet" aria-label="Permalink to &quot;Putting it together: failure modes cheat sheet&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom in production</th><th>Likely mechanism</th><th>Where to look</th></tr></thead><tbody><tr><td>Read replica returns stale rows</td><td>Async replication lag — the AP/EL choice</td><td>Replication lag metrics; read-your-writes routing</td></tr><tr><td>Duplicate writes after failover</td><td>Split-brain — old leader not fenced</td><td>Epoch/fencing tokens in the consensus layer</td></tr><tr><td>One shard at 100% CPU, rest idle</td><td>Hot key — skew defeats the partition function</td><td>Per-key write distribution, not per-partition</td></tr><tr><td>&quot;Newest&quot; record is actually older</td><td>Wall-clock last-write-wins + clock skew</td><td>Ordering source — use offsets/sequence, not timestamps</td></tr><tr><td>Transactions corrupt an invariant</td><td>Write skew under snapshot isolation</td><td>Isolation level; needs serializable or a materialized lock</td></tr><tr><td>Writes hang after one node dies</td><td>Quorum loss or sync-replica stall</td><td>Cluster membership, <code>min.insync.replicas</code>-style settings</td></tr></tbody></table><p>Every row above is one of the concepts in this chapter wearing a pager-duty costume.</p><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',6)),o(c,{questions:[{q:"During a network partition, what does CAP actually force you to choose?",options:["Between synchronous and asynchronous replication","Two of consistency, availability, partition tolerance","Consistency vs availability — partition tolerance is not optional","Whether to use a leader or quorum writes"],correct:2,explain:"Partition tolerance is a given in any distributed system — the network can always partition. The real choice is CP (refuse/deny writes) vs AP (serve potentially stale data), and it is made per subsystem, only during the partition."},{q:"PACELC adds which trade-off that CAP misses?",options:["Linearizability vs eventual consistency in multi-region writes","Latency vs cost during partitions","Load vs capacity under elastic scaling","Latency vs consistency when the network is healthy"],correct:3,explain:"Else (no partition) you still choose between Latency and Consistency — synchronous replication is consistent but adds RTT to every write; asynchronous is fast but risks losing recent writes on failover."},{q:"In a leaderless system with n=3, w=2, r=1, what can go wrong?",options:["Writes always fail","Reads can return stale data since w+r is not greater than n","Range scans become impossible","Split-brain between leaders"],correct:1,explain:"Quorum overlap requires w + r > n. With 2+1 = 3 = n there is no guaranteed overlap between write and read quorums — a read can hit the one replica that missed the write."},{q:"Hash partitioning user_id works fine until one celebrity user generates 30% of writes. Best mitigation?",options:["Salt the hot key — append a random bucket suffix to spread it across partitions","Add more partitions","Switch to range partitioning","Increase replication factor"],correct:0,explain:"The partition function cannot fix a skewed key. Salting (user_123#0..k) spreads one key across k partitions at the cost of scatter-gather reads. Range partitioning does not help — the hot key still lands in one shard."},{q:"Two on-call doctors each check that at least one doctor is on call, then both sign off — leaving zero. Which anomaly, and which isolation level prevents it?",options:["Lost update — repeatable read","Dirty read — read uncommitted","Write skew — serializable","Phantom — read committed"],correct:2,explain:"Each transaction reads a predicate, makes a locally valid decision, and the combination violates the invariant — classic write skew. Snapshot isolation (repeatable read) does NOT prevent it; true serializability (or a materialized lock row) does."},{q:"Your pipeline picks the newest record version by producer wall-clock timestamp and corrupt data appears after a deploy. Most likely cause?",options:["NTP clock drift or skew made an older write look newest","Quorum size too small","Too few partitions","Read committed isolation"],correct:0,explain:"Machine clocks drift and can jump backward. Ordering by producer wall-clock means a clock-skewed producer wins last-write-wins with stale data. Order by a single-authority sequence (offset/LSN) or use event-time + watermark policy instead."}]}),o(c,{questions:[{q:"With n = 3, w = 2, r = 2 and sloppy quorum enabled, why can a successful read still return stale data?",options:["Vector clocks disagree","The newest write may sit on a stand-in node outside the n home nodes until hinted handoff completes","Read repair has not run yet","w + r > n only works with a leader"],correct:1,explain:"A sloppy quorum counts any reachable nodes toward w, so the fresh copy can live outside the designated home nodes — reads touching only home nodes miss it until hinted handoff delivers the write. Sloppy quorum is a durability promise, not a consistency one."},{q:"How does Serializable Snapshot Isolation differ from two-phase locking?",options:["It is weaker — it allows phantoms","It locks predicates instead of rows","It requires a single-threaded executor","It is optimistic — transactions run on a snapshot and the DB aborts on dangerous interleavings, rather than blocking readers and writers"],correct:3,explain:"SSI keeps the snapshot-isolation property that readers never block writers; it tracks read/write dependencies and aborts a transaction when serializability would be violated. 2PL is pessimistic — it makes conflicts wait on locks. Under SSI you need bounded retry logic; aborted transactions are normal, not errors."},{q:"A user refreshes a dashboard and sees an older row count than the previous refresh. Which guarantee was violated?",options:["Consistent prefix reads","Monotonic reads","Read-your-writes","Linearizability"],correct:1,explain:"Seeing time go backward across successive reads is exactly what monotonic reads prevent — the fix is pinning each user to one replica (for example a hash of the user ID) or routing to a replica caught up to the last-seen position."}]}),e[16]||(e[16]=a('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><strong>Designing Data-Intensive Applications</strong> — Martin Kleppmann (2017), <a href="https://dataintensive.net/" target="_blank" rel="noreferrer">O&#39;Reilly Media / dataintensive.net</a> — the book this chapter compresses; chapters 5–9 (replication, partitioning, transactions, consistency/consensus) are the canonical treatment, Part III covers derived data.</li><li><a href="https://www.infoq.com/articles/cap-twelve-years-later-how-the-rules-have-changed/" target="_blank" rel="noreferrer">Harvest, Yield, and Scalable Tolerant Systems (CAP 12 years later) — Brewer</a> — the CAP author correcting the &quot;pick two&quot; misreading.</li><li><a href="https://www.cs.umd.edu/~abadi/papers/abadi-pacelc.pdf" target="_blank" rel="noreferrer">PACELC paper — Abadi</a> — the latency-vs-consistency extension.</li><li><a href="https://raft.github.io/raft.pdf" target="_blank" rel="noreferrer">Raft: In Search of an Understandable Consensus Algorithm</a> — plus the visualizations at <a href="https://raft.github.io/" target="_blank" rel="noreferrer">raft.github.io</a>.</li><li><a href="https://www.postgresql.org/docs/current/transaction-iso.html" target="_blank" rel="noreferrer">PostgreSQL transaction isolation docs</a> — exact anomaly semantics per level.</li><li><a href="https://cse.buffalo.edu/~demirbas/publications/hlc.pdf" target="_blank" rel="noreferrer">Logical Physical Clocks (HLC paper)</a> — how modern distributed DBs order events.</li><li><a href="https://jepsen.io/analyses" target="_blank" rel="noreferrer">Jepsen analyses</a> — what real databases actually deliver under partition, versus what they claim.</li></ul>',2))])}const q=u(m,[["render",g]]);export{C as __pageData,q as default};
